import XCTest

final class DriverUITests: XCTestCase {
    let outDir = "/private/var/folders/vl/g_dyzwvs4_52rz0rdks_3j900000gp/T/bench-tmp-v7f8jsuc/opencode/uidriver"

    func dump(_ name: String, _ app: XCUIApplication) {
        try? app.debugDescription.write(toFile: outDir + "/" + name + ".txt", atomically: true, encoding: .utf8)
    }

    func testNavigate() throws {
        let sb = XCUIApplication(bundleIdentifier: "com.apple.springboard")
        let openBtn = sb.alerts.buttons["Open"]
        if openBtn.waitForExistence(timeout: 5) { openBtn.tap() }
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.activate()
        sleep(2)

        let notif = app.staticTexts["Notifications on this device"]
        if !notif.exists {
            let settings = app.buttons["User settings"]
            if !settings.exists {
                let userMenu = app.buttons["User menu"]
                XCTAssertTrue(userMenu.waitForExistence(timeout: 10))
                userMenu.tap()
                sleep(2)
            }
            XCTAssertTrue(app.buttons["User settings"].waitForExistence(timeout: 5))
            app.buttons["User settings"].tap()
            sleep(2)
        }

        var tries = 0
        while !(notif.exists && notif.isHittable) && tries < 8 {
            app.swipeUp()
            tries += 1
        }
        XCTAssertTrue(notif.waitForExistence(timeout: 5))
        notif.tap()
        sleep(2)
        dump("dump6", app)
    }
}
